<template>
  <el-header class="topbar">
    <div class="topbar-left">
      <el-button text @click="$emit('toggle-sidebar')">
        <el-icon :size="20"><fold /></el-icon>
      </el-button>
      <span class="page-title">{{ pageTitle }}</span>
    </div>
    <div class="topbar-right">
      <el-tooltip :content="isDark ? t('topbar.themeToLight') : t('topbar.themeToDark')" placement="bottom">
        <el-button text @click="themeStore.toggleTheme">
          <el-icon :size="18">
            <sunny v-if="isDark" />
            <moon v-else />
          </el-icon>
        </el-button>
      </el-tooltip>

      <el-dropdown trigger="click" @command="handleLocaleCommand">
        <el-button text :aria-label="t('topbar.language')">
          <el-icon :size="18"><connection /></el-icon>
          <span class="locale-label">{{ currentShortLabel }}</span>
        </el-button>
        <template #dropdown>
          <el-dropdown-menu>
            <el-dropdown-item
              v-for="item in SUPPORTED_LOCALES"
              :key="item.code"
              :command="item.code"
              :disabled="locale === item.code"
            >
              {{ item.label }}
            </el-dropdown-item>
          </el-dropdown-menu>
        </template>
      </el-dropdown>

      <el-dropdown trigger="click" @command="handleCommand">
        <span class="user-info">
          <el-avatar :size="32" :icon="UserFilled" />
          <span class="username">{{ authStore.user?.username || t('topbar.user') }}</span>
          <el-icon><arrow-down /></el-icon>
        </span>
        <template #dropdown>
          <el-dropdown-menu>
            <el-dropdown-item command="profile" disabled>{{ t('topbar.profile') }}</el-dropdown-item>
            <el-dropdown-item divided command="logout">{{ t('topbar.logout') }}</el-dropdown-item>
          </el-dropdown-menu>
        </template>
      </el-dropdown>
    </div>
  </el-header>
</template>

<script setup lang="ts">
import { computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { UserFilled } from '@element-plus/icons-vue'
import { useI18n } from 'vue-i18n'
import { useThemeStore } from '@/stores/theme'
import { useAuthStore } from '@/stores/auth'
import { useLocale } from '@/composables/useLocale'
import { SUPPORTED_LOCALES, getLocaleConfig } from '@/locales'
import { logout } from '@/api/auth'
import { ElMessage } from 'element-plus'

const { t } = useI18n()
const route = useRoute()
const router = useRouter()
const themeStore = useThemeStore()
const authStore = useAuthStore()
const { locale, setLocale } = useLocale()

const currentShortLabel = computed(() => getLocaleConfig(locale.value).shortLabel)

const isDark = computed(() => themeStore.theme === 'dark')

const pageTitle = computed(() => {
  return (route.meta.title as string) || route.name?.toString() || 'ChaosOps'
})

defineEmits<{
  (e: 'toggle-sidebar'): void
}>()

function handleLocaleCommand(command: string) {
  setLocale(command)
}

async function handleCommand(command: string) {
  if (command === 'logout') {
    try {
      await logout()
      ElMessage.success(t('topbar.logoutSuccess'))
    } catch {
      // 即使退出接口失败也继续清理本地状态
    } finally {
      authStore.logout()
      router.push('/login')
    }
  }
}
</script>

