<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { useI18n } from 'vue-i18n'
import { useAuthStore } from '@/stores/auth'
import { getLicenseFeatures } from '@/api/license'
import { isMenuUnlocked, menuUpgradeHint, type FeatureMap } from '@/utils/edition'

defineProps<{
  collapsed?: boolean
}>()

const { t } = useI18n()
const route = useRoute()
const router = useRouter()
const authStore = useAuthStore()
const isAdmin = computed(() => authStore.isAdmin)

const activePath = computed(() => route.path)

// 当前 License 功能矩阵；null 表示未加载完成或获取失败。
// fail-closed：未获取到时受门控的菜单按锁定处理（后端门控是底线，此处仅体验）。
const features = ref<FeatureMap | null>(null)

onMounted(async () => {
  try {
    const data = await getLicenseFeatures()
    features.value = data.features
  } catch {
    features.value = null
  }
})

function isLocked(path: string): boolean {
  return !isMenuUnlocked(features.value, path)
}

function onSelect(index: string) {
  if (isLocked(index)) {
    // 沿用 ToolGeneration.vue 的引导模式：提示 + 跳转 License 页，不硬删路由
    ElMessage.warning(menuUpgradeHint(index))
    router.push('/settings/license')
    return
  }
  router.push(index)
}
</script>

