/**
 * 版本（edition）功能门控：侧边栏菜单项与 License 功能键的映射。
 *
 * 说明：后端门控（require_feature / get_api_key fail-closed）是底线，
 * 前端只做体验——不可用的菜单项置灰 + 锁图标 + 点击跳升级提示，不硬删路由。
 */
import i18n from '@/locales'

export type FeatureMap = Record<string, boolean | number | string>

export interface MenuFeatureGate {
  /** 对应后端 _FEATURE_MATRIX 中的功能键 */
  feature: string
  /** 解锁该功能所需的最低版本（用于升级提示文案） */
  minEdition: 'professional' | 'enterprise'
}

/** 受 License 门控的菜单项路径 -> 功能键映射 */
export const MENU_FEATURE_GATES: Record<string, MenuFeatureGate> = {
  // 专业版及以上
  '/nodes/bulk': { feature: 'bulk_registration', minEdition: 'professional' },
  '/remote/execute': { feature: 'remote_execution', minEdition: 'professional' },
  '/notifier/im-channels': { feature: 'im_channels', minEdition: 'professional' },
  '/settings/ai-heal': { feature: 'ai_heal', minEdition: 'professional' },
  '/settings/users': { feature: 'multi_user_rbac', minEdition: 'professional' },
  // 企业版专属
  '/ai/tools': { feature: 'ai_custom_tool', minEdition: 'enterprise' },
  '/ai/optimizer': { feature: 'ai_self_optimization', minEdition: 'enterprise' },
  '/settings/api-keys': { feature: 'open_api', minEdition: 'enterprise' },
  '/settings/webhooks': { feature: 'open_api', minEdition: 'enterprise' },
}

/**
 * 判断菜单项在当前 License 功能矩阵下是否可用。
 *
 * fail-closed：功能矩阵未加载（null/undefined）时，受门控的菜单一律按锁定处理
 * （后端同样会拦截，前端只是提前给出引导）。
 */
export function isMenuUnlocked(
  features: FeatureMap | null | undefined,
  path: string
): boolean {
  const gate = MENU_FEATURE_GATES[path]
  if (!gate) return true
  if (!features) return false
  const value = features[gate.feature]
  // 兼容后端遗留的 "trial" 取值（视为可用，与 check_feature_enabled 语义一致）
  return value === true || value === 'trial'
}

/** 菜单锁定时的升级提示文案（沿用 ToolGeneration.vue 的引导模式）。 */
export function menuUpgradeHint(path: string): string {
  const gate = MENU_FEATURE_GATES[path]
  if (!gate) return ''
  // 普通 ts 模块没有组件上下文，直接用全局 i18n 实例取翻译
  const editionName =
    gate.minEdition === 'enterprise'
      ? i18n.global.t('edition.enterprise')
      : i18n.global.t('edition.professional')
  return i18n.global.t('edition.upgradeHint', { edition: editionName })
}
